"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["66841"],{33159(e){e.exports=JSON.parse('{"id":"F270","slug":"etf-premium-tracking","name":"ETF Premium/Discount and Tracking Difference","subject":"Equity Markets","section":"Equities","topic":"Exchange-traded funds (ETFs)","level":"Intermediate","aliases":["ETF NAV gap","tracking difference","creation and redemption","ETF cost"],"formula":{"latex":"\\\\text{Premium}=\\\\frac{P-NAV}{NAV},\\\\quad TD=R_{ETF}-R_{index}","also":[],"text":"Premium (or discount) = (Market price - NAV) / NAV; Tracking difference = ETF return - Index return"},"symbols":[{"symbol":"P","meaning":"Price at which the ETF trades on the exchange","unit":"money"},{"symbol":"NAV","meaning":"Value of the ETF\'s holdings per share","unit":"money"},{"symbol":"R_ETF","meaning":"Return of the ETF over the period","unit":"percent"},{"symbol":"R_index","meaning":"Return of the index it follows","unit":"percent"}],"when_to_use":"Use the premium to check whether an ETF trades near the value of its holdings. Large gaps get closed by authorized participants, who create or redeem shares. Use the tracking difference to see what fees and frictions cost compared with the index.","worked_example":{"problem":"An ETF trades at 100.15 while its NAV is 100.00. Over a year it returned 9.72% and its index returned 9.90%. What are the premium and the tracking difference?","inputs":{"p":100.15,"nav":100,"re":9.72,"ri":9.9},"steps":[{"label":"Premium = (price - NAV) / NAV","working":"(100.15-100) / 100","value":"0.150%"},{"label":"Tracking difference = ETF return - index return","working":"0.0972-0.099","value":"-0.18%"}],"answer":"The ETF trades at a premium of 0.150%. Its tracking difference is -0.18%, close to its annual fee, so it follows the index closely."},"calculator":{"available":true,"inputs":[{"id":"p","label":"Market price","unit":"money","type":"number","default":100.15,"hint":""},{"id":"nav","label":"NAV per share","unit":"money","type":"number","default":100,"hint":""},{"id":"re","label":"ETF return","unit":"%","type":"number","default":9.72,"hint":""},{"id":"ri","label":"Index return","unit":"%","type":"number","default":9.9,"hint":""}],"checks":[{"expr":"nav>0","message":"The NAV must be above zero."}],"steps":[{"id":"prem","label":"Premium = (price - NAV) / NAV","expr":"(p-nav)/nav","format":"pct3"},{"id":"td","label":"Tracking difference = ETF return - index return","expr":"re-ri","format":"pct2"}],"results":["prem","td"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"prem":0.0015,"td":-0.0018}},"finder":{"finds":"Whether an ETF trades fairly and tracks its index","needs":"Price, NAV, ETF and index returns"},"related":[{"slug":"nav-per-share","name":"Net Asset Value per Share"},{"slug":"information-ratio","name":"Information Ratio and Tracking Error"},{"slug":"fee-drag","name":"Cost of Fees: Active vs. Passive"}],"related_ids":["F269","F248","F244"],"group":"Markets and instruments","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mtext>Premium</mtext><mo>=</mo><mfrac><mrow><mi>P</mi><mo>\u2212</mo><mi>N</mi><mi>A</mi><mi>V</mi></mrow><mrow><mi>N</mi><mi>A</mi><mi>V</mi></mrow></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>T</mi><mi>D</mi><mo>=</mo><msub><mi>R</mi><mrow><mi>E</mi><mi>T</mi><mi>F</mi></mrow></msub><mo>\u2212</mo><msub><mi>R</mi><mrow><mi>i</mi><mi>n</mi><mi>d</mi><mi>e</mi><mi>x</mi></mrow></msub></mrow><annotation encoding=\\"application/x-tex\\">\\\\text{Premium}=\\\\frac{P-NAV}{NAV},\\\\quad TD=R_{ETF}-R_{index}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"estate-tax-basic","name":"Estate Tax Estimate"},"next":{"slug":"gas-fee-cost","name":"Ethereum Gas Fee Cost"},"lesson":null,"total":522}')}}]);